import java.util.*;
import java.math.*;
import java.io.*;

public class Main {
    static FastReader scan = new FastReader();
    static PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

    static int mod(int x, int y) {
        if (x < 0)
            x = x + (-x / y + 1) * y;
        return x % y;
    }

    static int A = 400, n;
    static int[] l = new int[5050];
    static int[] r = new int[5050];
    static char[] c = new char[5050];

    static int solve(int x) {
        int a = 0, b = 0;
        for (int i = 0; i < n; i++) {
            if (x < l[i] || x > r[i])
                continue;
            if (c[i] == 'M')
                a++;
            else b++;
        }
        return Math.min(a, b);
    }

    public static void main(String[] args) throws IOException {
        n = scan.nextInt();
        String s = scan.next();
        int cur = 0, cnt = 0, maxA = 0, maxB = 0;
        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '(' || ch == ')' || ch == '_') {
                if (cnt > 0) {
                    if (cur > 0) maxB++;
                    else maxA = Math.max(maxA, cnt);
                    cnt = 0;
                }
                if (ch == '(') cur = 1;
                if (ch == ')') cur = 0;
            } else {
                cnt++;
            }
        }
        maxA = Math.max(maxA, cnt);
        out.println(maxA + " " + maxB);
        out.close();
    }

    static long pow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result *= base;
            base *= base;
            exp >>= 1;
        }
        return result;
    }

    static void sort(long[] arr) {
        List<Long> list = new ArrayList<>();
        for (long val : arr) list.add(val);
        Collections.sort(list);
        for (int i = 0; i < list.size(); ++i) arr[i] = list.get(i);
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return str;
        }

        public int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    static class Pair {
        int first, second;
        Pair(int f, int s) {
            first = f;
            second = s;
        }
    }
}
